53	impl<'a> ToPrimitive<'a> for Expression<'a> {
54	    fn to_primitive(&self, ctx: &impl GlobalContext<'a>) -> ToPrimitiveResult {
55	        match self.value_type(ctx) {
56	            ValueType::Undefined => ToPrimitiveResult::Undefined,
57	            ValueType::Null => ToPrimitiveResult::Null,
58	            ValueType::Number => ToPrimitiveResult::Number,
59	            ValueType::BigInt => ToPrimitiveResult::BigInt,
60	            ValueType::String => ToPrimitiveResult::String,
61	            ValueType::Boolean => ToPrimitiveResult::Boolean,
62	            ValueType::Object | ValueType::Undetermined => {
63	                match self {
64	                    Expression::RegExpLiteral(_) | Expression::ArrayExpression(_) => {
65	                        ToPrimitiveResult::String
66	                    }
67	                    // unless `Symbol.toPrimitive`, `valueOf`, `toString` is overridden,
68	                    // ToPrimitive for an object returns `"[object Object]"`
69	                    Expression::ObjectExpression(obj) => {
70	                        if maybe_object_with_to_primitive_related_properties_overridden(obj) {
71	                            ToPrimitiveResult::Undetermined
72	                        } else {
73	                            ToPrimitiveResult::String
74	                        }
75	                    }
76	                    _ => ToPrimitiveResult::Undetermined,
77	                }
78	            }
79	        }
80	    }
81	}
