/// Whether a built-in constructor call is free of side effects other than those caused by
/// evaluating its arguments.
///
/// Some constructors coerce or iterate their argument, which can invoke user-defined code
/// (`toString`/`valueOf`/`Symbol.toPrimitive`/`Symbol.iterator`), throw, or otherwise have
/// side effects. This function conservatively determines whether such a coercion/iteration is
/// guaranteed to be side-effect-free for the given arguments. The caller is still responsible
/// for checking whether evaluating the arguments themselves has side effects.
fn is_pure_constructor_call<'a>(
    name: &str,
    args: &[Argument<'a>],
    ctx: &impl MayHaveSideEffectsContext<'a>,
) -> bool {
    match name {
        // These constructors never coerce or iterate their argument, so they are pure
        // regardless of the argument passed (including unknown references and object literals).
        "Object" | "Boolean" | "ArrayBuffer" | "Error" | "EvalError" | "RangeError"
        | "ReferenceError" | "SyntaxError" | "TypeError" | "URIError" => true,

        // The `String` and `Number` wrappers coerce their argument via `ToString`/`ToNumber`,
        // which can invoke a user-defined `toString`/`valueOf`/`Symbol.toPrimitive`. This is only
        // safe when the argument's primitive value can be statically determined (a known primitive
        // or a plain object literal without a custom conversion method).
        "String" | "Number" => match args.first() {
            None => true,
            Some(arg) => arg
                .as_expression()
                .is_some_and(|e| e.to_primitive(ctx) != ToPrimitiveResult::Undetermined),
        },

        // `Date` uses numeric and string arguments directly, but coerces anything else.
        "Date" => args.iter().all(|arg| {
            matches!(
                arg.as_expression(),
                Some(Expression::NumericLiteral(_) | Expression::StringLiteral(_))
            )
        }),

        // `Buffer` allocates a buffer of a given length for a numeric argument, but coerces or
        // iterates anything else.
        "Buffer" => match args.first() {
            None => true,
            Some(arg) => matches!(arg.as_expression(), Some(Expression::NumericLiteral(_))),
        },

        // Typed array constructors iterate their argument via `Symbol.iterator` (which can invoke
        // a custom iterator). A numeric argument sets the length, and a plain object literal
        // without a custom iterator is treated as an array-like without invoking user code.
        _ if is_typed_array_constructor(name) => match args.first() {
            None => true,
            Some(arg) => match arg.as_expression() {
                Some(Expression::NumericLiteral(_)) => true,
                Some(Expression::ObjectExpression(obj)) => {
                    !maybe_object_with_iterator_overridden(obj)
                }
                _ => false,
            },
        },

        _ => false,
    }
}

/// Whether an object literal might define a custom `Symbol.iterator`.
///
/// A `Symbol.iterator` can only be defined via a computed key, so an object literal whose keys are
/// all static (identifiers, string/numeric/template literals) cannot override it. Spread elements
/// may bring in an iterator unless they are known iterables without a custom iterator.
fn maybe_object_with_iterator_overridden(obj: &ObjectExpression<'_>) -> bool {
    obj.properties.iter().any(|prop| match prop {
        ObjectPropertyKind::ObjectProperty(prop) => match &prop.key {
            PropertyKey::StaticIdentifier(_)
            | PropertyKey::PrivateIdentifier(_)
            | PropertyKey::StringLiteral(_)
            | PropertyKey::NumericLiteral(_)
            | PropertyKey::TemplateLiteral(_) => false,
            // A computed key could be `[Symbol.iterator]`.
            _ => true,
        },
        ObjectPropertyKind::SpreadProperty(e) => match &e.argument {
            Expression::ObjectExpression(obj) => maybe_object_with_iterator_overridden(obj),
            // Arrays and strings expose the built-in iterator, not a user-defined one.
            Expression::ArrayExpression(_)
            | Expression::StringLiteral(_)
            | Expression::TemplateLiteral(_) => false,
            _ => true,
        },
    })
