use oxc_parser::Parser;
use oxc_span::SourceType;

struct Ctx {
    globals: FxHashSet<&'static str>,
}

impl<'a> GlobalContext<'a> for Ctx {
    fn is_global_reference(&self, ident: &IdentifierReference<'a>) -> bool {
        self.globals.contains(ident.name.as_str())
    }
}

impl MayHaveSideEffectsContext<'_> for Ctx {
    fn annotations(&self) -> bool {
        true
    }
    fn manual_pure_functions(&self, _callee: &Expression) -> bool {
        false
    }
    fn property_read_side_effects(&self) -> PropertyReadSideEffects {
        PropertyReadSideEffects::All
    }
    fn property_write_side_effects(&self) -> bool {
        true
    }
    fn unknown_global_side_effects(&self) -> bool {
        true
    }
}

fn check(src: &str, expected: bool, globals: &[&'static str]) {
    let ctx = Ctx { globals: globals.iter().copied().collect() };
    let allocator = Allocator::default();
    let ret = Parser::new(&allocator, src, SourceType::mjs()).parse();
    let Some(Statement::ExpressionStatement(stmt)) = ret.program.body.first() else {
        panic!("no expr stmt: {src}");
    };
    let got = stmt.expression.may_have_side_effects(&ctx);
    let status = if got == expected { "ok  " } else { "FAIL" };
    println!("[{status}] {src} => got={got} expected={expected}");
}

fn main() {
    let g = &["String", "Number", "Date", "Buffer", "Object", "Boolean", "Error", "TypeError",
